import { useEffect, useState } from "react";
import { createProject, getProjects, type Project, deleteProject, updateProjectResolved } from "../api/projects";
import { ThemeToggle } from "../components/ThemeToggle";
import { useTheme } from "../theme/useTheme";

function goToProject(projectId: string) {
  if (!projectId || projectId === "undefined" || projectId === "null") return;

  const url = new URL(window.location.href);
  url.searchParams.set("projectId", projectId);
  window.history.pushState({}, "", url);
  window.dispatchEvent(new PopStateEvent("popstate")); // trigger react to update page
}

export default function ProjectsPage() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [name, setName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const { theme, toggleTheme } = useTheme();

  const csrfToken =
    document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content ?? "";

  async function refresh() {
    setError(null);
    try {
      const p = await getProjects();
      setProjects(p);
    } catch (e: any) {
      setError(e?.message ?? "Failed to load projects");
    }
  }

  useEffect(() => {
    refresh();
  }, []);

  async function onCreate() {
    if (!name.trim()) return;
    setBusy(true);
    setError(null);

    try {
      const created = await createProject({ Name: name.trim() });
      setName("");
      setProjects((prev) => [created, ...prev]);
    } catch (e: any) {
      setError(e?.message ?? "Create failed");
    } finally {
      setBusy(false);
    }
  }

  async function onDelete(projectId: string) {
    setBusy(true);
    setError(null);
    try {
      await deleteProject(projectId);
      setProjects((prev) => prev.filter((p) => p.Id !== projectId));
      setConfirmDelete(null);
    } catch (e: any) {
      setError(e?.message ?? "Delete failed");
    } finally {
      setBusy(false);
    }
  }

  async function onResolvedChange(projectId: string, isResolved: boolean) {
    setBusy(true);
    setError(null);
    try {
      await updateProjectResolved(projectId, isResolved);
      setProjects((prev) => prev.map((p) => p.Id === projectId ? { ...p, IsResolved: isResolved } : p));
    } catch (e: any) {
      setError(e?.message ?? "Update failed");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="wrap">
      <div className="pageHeader">
        <div>
          <h1 className="title">Projects</h1>
          <p className="sub">Choose a project or create a new one.</p>
        </div>

        {/* Right side actions */}
        <div className="toolbar" style={{ alignItems: "center" }}>
          <ThemeToggle theme={theme} onToggle={toggleTheme} />

          <form method="post" action="/logout" style={{ margin: 0 }}>
            <input type="hidden" name="__RequestVerificationToken" value={csrfToken} />
            <button className="secondary" type="submit">
              Sign out
            </button>
          </form>
        </div>
      </div>

      {/* Create new project */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          onCreate();
        }}
        className="toolbar"
        style={{ marginBottom: 16 }}
      >
        <input
          className="input"
          placeholder="New project name…"
          value={name}
          onChange={(e) => setName(e.target.value)}
          style={{ width: 260 }}
        />
        <button className="btn" type="submit" disabled={busy}>
          + Create
        </button>
      </form>

      {error ? (
        <div className="error">
          <strong>Error:</strong> {error}
        </div>
      ) : null}

      <div style={{ display: "grid", gap: 12 }}>
        {projects
          .sort((a, b) => {
            if (a.IsResolved === b.IsResolved) return 0;
            return a.IsResolved ? 1 : -1; // unresolved first
          })
          .map((p) => (
          <div
            key={p.Id}
            className="card"
            style={{
              cursor: "pointer",
              backgroundColor: p.IsResolved ? "#006400" : undefined, // dark green
            }}
            onClick={() => goToProject(p.Id)}
            role="button"
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div className="cardTitle">{p.Name}</div>
                <div className="cardDesc">Created {new Date(p.CreatedAtUtc).toLocaleString()}</div>
              </div>
              <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 4 }}>
                <label 
                  style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 12 }}
                  onClick={(e) => e.stopPropagation()}
                >
                  <input
                    type="checkbox"
                    checked={p.IsResolved}
                    onChange={(e) => {
                      e.stopPropagation();
                      onResolvedChange(p.Id, e.target.checked);
                    }}
                  />
                  Resolved
                </label>
                <button
                  className="danger"
                  style={{ fontSize: 12, padding: "4px 8px" }}
                  onClick={(e) => {
                    e.stopPropagation();
                    setConfirmDelete(p.Id);
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        ))}

        {projects.length === 0 ? <div className="pill">No projects yet</div> : null}
      </div>

      {confirmDelete && (
        <div className="backdrop" onClick={() => setConfirmDelete(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>Are you sure you want to delete this project?</h3>
            <div className="actions">
              <button className="secondary" onClick={() => setConfirmDelete(null)}>
                Cancel
              </button>
              <button className="danger" onClick={() => onDelete(confirmDelete)} disabled={busy}>
                Yes
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

