import { useEffect, useId, useState } from "react";
import type { Task, TaskStatus } from "../../api/tasks";

export function TaskModal(props: {
  mode: "create" | "edit";
  initialTask?: Task;
  defaultStatus?: TaskStatus;
  onClose: () => void;

  onCreate: (input: { Title: string; Description?: string | null; Status: TaskStatus }) => void;
  onUpdate: (id: string, input: { Title: string; Description?: string | null; Status: TaskStatus }) => void;
  onDelete: (id: string) => void;
}) {
  const [Title, setTitle] = useState("");
  const [Description, setDescription] = useState<string>("");
  const [Status, setStatus] = useState<TaskStatus>(props.defaultStatus ?? "ToDo");

  // unika id:n för label/input-koppling (fixar warnings)
  const modalTitleId = useId();
  const titleId = useId();
  const descriptionId = useId();
  const statusId = useId();

  useEffect(() => {
    if (props.mode === "edit" && props.initialTask) {
      setTitle(props.initialTask.Title);
      setDescription(props.initialTask.Description ?? "");
      setStatus(props.initialTask.Status);
    } else {
      setTitle("");
      setDescription("");
      setStatus(props.defaultStatus ?? "ToDo");
    }
  }, [props.mode, props.initialTask, props.defaultStatus]);

  function save() {
    const trimmedTitle = Title.trim();
    const trimmedDescription = Description.trim();

    if (!trimmedTitle) return;

    if (props.mode === "create") {
      props.onCreate({
        Title: trimmedTitle,
        Description: trimmedDescription || null,
        Status,
      });
    } else if (props.initialTask) {
      props.onUpdate(props.initialTask.Id, {
        Title: trimmedTitle,
        Description: trimmedDescription || null,
        Status,
      });
    }

    props.onClose();
  }

  function remove() {
    if (!props.initialTask) return;
    props.onDelete(props.initialTask.Id);
    props.onClose();
  }

  return (
    <div className="backdrop" onClick={props.onClose} role="presentation">
      <div
        className="modal"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby={modalTitleId}
      >
        <h3 id={modalTitleId} style={{ marginTop: 0 }}>
          {props.mode === "create" ? "Create task" : "Edit task"}
        </h3>

        <div className="row">
          <label htmlFor={titleId}>Title</label>
          <input
            id={titleId}
            name="title"
            className="input"
            value={Title}
            onChange={(e) => setTitle(e.target.value)}
            autoComplete="off"
            autoFocus
          />
        </div>

        <div className="row">
          <label htmlFor={descriptionId}>Description</label>
          <textarea
            id={descriptionId}
            name="description"
            className="textarea"
            rows={4}
            value={Description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </div>

        <div className="row">
          <label htmlFor={statusId}>Status</label>
          <select
            id={statusId}
            name="status"
            className="select"
            value={Status}
            onChange={(e) => setStatus(e.target.value as TaskStatus)}
          >
            <option value="ToDo">ToDo</option>
            <option value="InProgress">InProgress</option>
            <option value="Done">Done</option>
          </select>
        </div>

        <div className="actions">
          {props.mode === "edit" ? (
            <button className="danger" type="button" onClick={remove}>
              Delete
            </button>
          ) : (
            <span />
          )}

          <div style={{ display: "flex", gap: 10 }}>
            <button className="secondary" type="button" onClick={props.onClose}>
              Cancel
            </button>
            <button className="primary" type="button" onClick={save} disabled={!Title.trim()}>
              Save
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

