import type { ThemeMode } from "../theme/useTheme";

export function ThemeToggle({
  theme,
  onToggle,
}: {
  theme: ThemeMode;
  onToggle: () => void;
}) {
  // Krav: visa "Light mode" när man är i dark, och tvärtom
  const label = theme === "dark" ? "Light mode" : "Dark mode";

  return (
    <button type="button" className="themeToggleWrap" onClick={onToggle}>
      <span className={`themeToggle ${theme === "light" ? "isLight" : "isDark"}`}>
        <span className="themeToggleKnob" />
        <span className="themeToggleIcon">{theme === "dark" ? "🌙" : "☀️"}</span>
      </span>
      <span className="themeToggleLabel">{label}</span>
    </button>
  );
}