import { useState } from "react";
import { addProjectMember } from "../../api/projects";

export function ShareModal({
  projectId,
  onClose,
}: {
  projectId: string;
  onClose: () => void;
}) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<"Member" | "Owner">("Member");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState<string | null>(null);

  async function submit() {
    if (!email.trim()) return;
    setBusy(true);
    setError(null);
    setDone(null);

    try {
      const res = await addProjectMember(projectId, { Email: email.trim(), Role: role });
      if (res.added) setDone("User added to project successfully.");
      else setDone(res.reason ?? "User already has access.");
      setEmail("");
    } catch (e: any) {
      setError(e?.message ?? "Share failed");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="backdrop" onClick={onClose} role="presentation">
      <div className="modal" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true">
        <h3 style={{ marginTop: 0 }}>Share project</h3>

        {error ? (
          <div className="error">
            <strong>Error:</strong> {error}
          </div>
        ) : null}

        {done ? <div className="pill">{done}</div> : null}

        <div className="row">
          <label htmlFor="share-email">User email</label>
          <input
            id="share-email"
            name="share-email"
            className="input"
            placeholder="name@company.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            autoComplete="email"
          />
        </div>

        <div className="row">
          <label htmlFor="share-role">Role</label>
          <select
            id="share-role"
            name="share-role"
            className="select"
            value={role}
            onChange={(e) => setRole(e.target.value as any)}
          >
            <option value="Member">Member</option>
            <option value="Owner">Owner</option>
          </select>
        </div>

        <div className="actions">
          <span />
          <div style={{ display: "flex", gap: 10 }}>
            <button className="secondary" type="button" onClick={onClose}>
              Close
            </button>
            <button className="primary" type="button" onClick={submit} disabled={busy}>
              Share
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
