// CRUD + state + grouped + persistColumn 
// använder API funktioner från api/tasks och gruppindelning från selectors.ts och exponerar allt som behövs för Board.tsx
import { useEffect, useMemo, useRef, useState } from "react";
import type { Task, TaskStatus } from "../../../api/tasks";
import { createTask, deleteTask, getTasks, updateTask, reorderTasks } from "../../../api/tasks";
import { groupTasks } from "./selectors";
import { useProjectRealtime } from "../../../realtime/useProjectRealtime";

export function useBoardTasks(projectId: string) {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [syncing, setSyncing] = useState(false);

  // Initial load (en gång när projectId ändras)
  useEffect(() => {
    let alive = true;

    (async () => {
      try {
        const data = await getTasks(projectId);
        if (alive) setTasks(data);
      } catch (e: any) {
        if (alive) setError(String(e?.message ?? e));
      }
    })();

    return () => {
      alive = false;
    };
  }, [projectId]);

  const grouped = useMemo(() => groupTasks(tasks), [tasks]);

  async function reload() {
    const fresh = await getTasks(projectId);
    setTasks(fresh);
  }

  // SignalR: instant reload när någon annan ändrar tasks.
  // Undvik reload när vi självmant uppdaterar, annars kan UI hoppa.
  const syncingRef = useRef(syncing);
  useEffect(() => {
    syncingRef.current = syncing;
  }, [syncing]);

  useProjectRealtime(projectId, () => {
    if (syncingRef.current) return;
    reload().catch(() => {});
  });

  async function persistColumn(status: TaskStatus, ordered: Task[]) {
    setError(null);
    setSyncing(true);
    try {
      // 1) Normalisera enligt UI-ordning
      const normalized = ordered.map((t, i) => ({ ...t, Status: status, Priority: i + 1 }));

      // 2) Optimistic UI
      const byId = new Map(normalized.map((t) => [t.Id, t]));
      setTasks((prev) =>
        prev.map((t) => {
          const u = byId.get(t.Id);
          return u ? { ...t, Status: u.Status, Priority: u.Priority } : t;
        })
      );

      // 3) Atomisk reorder (1 request)
      await reorderTasks(projectId, status, normalized.map((t) => t.Id));

      // 4) En GET efteråt (säker synk)
      const fresh = await getTasks(projectId);
      setTasks(fresh);
    } catch (e: any) {
      setError(e?.message ?? "Reorder failed");
      // fallback: försök hämta om läget efter fel
      try {
        const fresh = await getTasks(projectId);
        setTasks(fresh);
      } catch {}
    } finally {
      setSyncing(false);
    }
  }

  async function onCreate(input: { Title: string; Description?: string | null; Status: TaskStatus }) {
    setError(null);
    setSyncing(true);
    try {
      const created = await createTask(projectId, {
        Title: input.Title,
        Description: input.Description ?? null,
      });

      const currentList = grouped[input.Status] ?? [];
      const nextPriority = (currentList[currentList.length - 1]?.Priority ?? 0) + 1;

      const finalTask = await updateTask(projectId, created.Id, {
        Title: created.Title,
        Description: created.Description ?? null,
        Status: input.Status,
        Priority: nextPriority,
      });

      setTasks((prev) => [finalTask, ...prev]);
    } catch (e: any) {
      setError(e?.message ?? "Create failed");
    } finally {
      setSyncing(false);
    }
  }

  async function onUpdate(
    id: string,
    patch: { Title: string; Description?: string | null; Status: TaskStatus; Priority?: number }
  ) {
    setError(null);
    setSyncing(true);

    const current = tasks.find((t) => t.Id === id);
    if (!current) {
      setSyncing(false);
      return;
    }

    const nextPriority = patch.Priority ?? current.Priority;

    const optimistic: Task = {
      ...current,
      Title: patch.Title,
      Description: patch.Description ?? null,
      Status: patch.Status,
      Priority: nextPriority,
    };

    setTasks((prev) => prev.map((t) => (t.Id === id ? optimistic : t)));

    try {
      const updated = await updateTask(projectId, id, {
        Title: patch.Title,
        Description: patch.Description ?? null,
        Status: patch.Status,
        Priority: nextPriority,
      });

      setTasks((prev) => prev.map((t) => (t.Id === id ? updated : t)));
    } catch (e: any) {
      setTasks((prev) => prev.map((t) => (t.Id === id ? current : t)));
      setError(e?.message ?? "Update failed");
    } finally {
      setSyncing(false);
    }
  }

  async function onDelete(id: string) {
    setError(null);
    setSyncing(true);

    const before = tasks;
    const deleted = tasks.find((t) => t.Id === id);
    if (!deleted) {
      setSyncing(false);
      return;
    }

    const status = deleted.Status;

    const remaining = tasks.filter((t) => t.Id !== id);
    setTasks(remaining);

    try {
      await deleteTask(projectId, id);

      // Efter delete: normalisera kolumnen atomiskt också
      const col = remaining
        .filter((t) => t.Status === status)
        .sort((a, b) => (a.Priority ?? 0) - (b.Priority ?? 0));

      await persistColumn(status, col);
    } catch (e: any) {
      setTasks(before);
      setError(e?.message ?? "Delete failed");
    } finally {
      setSyncing(false);
    }
  }

  return {
    tasks,
    setTasks,
    grouped,
    error,
    setError,
    syncing,
    setSyncing,
    reload,
    persistColumn,
    onCreate,
    onUpdate,
    onDelete,
  };
}
