import { useEffect, useState } from "react";
import ProjectsPage from "./pages/ProjectsPage";
import ProjectDashboardPage from "./pages/ProjectDashboardPage";

function readProjectId(): string | null {
  const url = new URL(window.location.href);
  const pid = url.searchParams.get("projectId");
  if (!pid || pid === "undefined" || pid === "null") return null;
  return pid;
}

export default function App() {
  const [projectId, setProjectId] = useState<string | null>(() => readProjectId());

  useEffect(() => {
    const onPop = () => setProjectId(readProjectId());
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  if (!projectId) return <ProjectsPage />;
  return <ProjectDashboardPage projectId={projectId} />;
}



