import { useState } from "react";
import {
  DndContext,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";

import type { Task, TaskStatus } from "../../api/tasks";
import { Column } from "./Column";
import { TaskModal } from "./TaskModal";
import { TaskCardPreview } from "./TaskCardPreview";

import { COLS } from "./board/config";
import { useBoardTasks } from "./board/useBoardTasks";
import { useBoardDrag } from "./board/useBoardDrag";
import { collisionDetection } from "./board/dnd"; // ✅ viktig

type ModalState =
  | { open: false }
  | { open: true; mode: "create"; status: TaskStatus }
  | { open: true; mode: "edit"; task: Task };

export function Board({ projectId }: { projectId: string }) {
  if (!projectId) throw new Error("Board requires a projectId");

  const [activeId, setActiveId] = useState<string | null>(null);
  const [modal, setModal] = useState<ModalState>({ open: false });

  const {
    tasks,
    grouped,
    error,
    setError,
    syncing,
    setSyncing,
    persistColumn,
    reload,
    onCreate,
    onUpdate,
    onDelete,
  } = useBoardTasks(projectId);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } })
  );

  const onDragEnd = useBoardDrag({
  projectId,
  tasks,
  grouped,
  syncing,
  setSyncing,
  setError,
  persistColumn,
  reload,
  });




  const activeTask = activeId ? tasks.find((t) => t.Id === activeId) ?? null : null;

  const csrfToken =
    document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content ?? "";

  return (
    <>
      {error ? (
        <div className="error">
          <strong>Error:</strong> {error}
        </div>
      ) : null}

      <div className="toolbar" style={{ justifyContent: "flex-end", marginBottom: 12 }}>
        <form method="post" action="/logout" style={{ margin: 0 }}>
          <input type="hidden" name="__RequestVerificationToken" value={csrfToken} />
          <button className="secondary" type="submit">
            Sign out
          </button>
        </form>
      </div>

      <DndContext
        sensors={sensors}
        collisionDetection={collisionDetection} 
        onDragStart={(e) => setActiveId(String(e.active.id))}
        onDragCancel={() => setActiveId(null)}
        onDragEnd={async (e) => {
          await onDragEnd(e);
          setActiveId(null);
        }}
      >
        <div className="board">
          {COLS.map((col) => (
            <Column
              key={col.status}
              title={col.title}
              status={col.status}
              tasks={grouped[col.status]}
              onAdd={() => setModal({ open: true, mode: "create", status: col.status })}
              onOpenTask={(task) => setModal({ open: true, mode: "edit", task })}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCardPreview task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>

      {modal.open && modal.mode === "create" ? (
        <TaskModal
          mode="create"
          defaultStatus={modal.status}
          onClose={() => setModal({ open: false })}
          onCreate={onCreate}
          onUpdate={() => {}}
          onDelete={() => {}}
        />
      ) : null}

      {modal.open && modal.mode === "edit" ? (
        <TaskModal
          mode="edit"
          initialTask={modal.task}
          onClose={() => setModal({ open: false })}
          onCreate={() => {}}
          onUpdate={(id, patch) =>
            onUpdate(id, {
              Title: patch.Title,
              Description: patch.Description ?? null,
              Status: patch.Status,
            })
          }
          onDelete={onDelete}
        />
      ) : null}
    </>
  );
}
