import { apiFetch } from "./API";

export type TaskStatus = "ToDo" | "InProgress" | "Done";

export type Task = {
  Id: string;
  Title: string;
  Description?: string | null;
  Status: TaskStatus;
  Priority: number;
  CreatedAtUtc: string;
  LastChangedByUserId?: string | null;
  ProjectId: string;
};

function assertProjectId(projectId: string) {
  if (!projectId || projectId === "undefined" || projectId === "null") {
    throw new Error("Invalid projectId passed to tasks API: " + String(projectId));
  }
}

export async function reorderTasks(
  projectId: string,
  status: TaskStatus,
  orderedTaskIds: string[]
): Promise<void> {
  assertProjectId(projectId);

  await apiFetch(`/projects/${projectId}/tasks/reorder`, {
    method: "PUT",
    body: JSON.stringify({
      Status: status,
      OrderedTaskIds: orderedTaskIds,
    }),
  });
}

export async function getTasks(projectId: string): Promise<Task[]> {
  assertProjectId(projectId);

  const res = await apiFetch(`/projects/${projectId}/tasks`);
  return (await res.json()) as Task[];
}

export async function createTask(
  projectId: string,
  input: { Title: string; Description?: string | null }
): Promise<Task> {
  assertProjectId(projectId);

  const res = await apiFetch(`/projects/${projectId}/tasks`, {
    method: "POST",
    body: JSON.stringify({ Title: input.Title, Description: input.Description ?? null }),
  });

  return (await res.json()) as Task;
}

export async function updateTask(
  projectId: string,
  taskId: string,
  input: { Title: string; Description?: string | null; Status: TaskStatus; Priority: number }
): Promise<Task> {
  assertProjectId(projectId);
  if (!taskId) throw new Error("updateTask called with empty taskId");

  const res = await apiFetch(`/projects/${projectId}/tasks/${taskId}`, {
    method: "PUT",
    body: JSON.stringify({
      Title: input.Title,
      Description: input.Description ?? null,
      Status: input.Status,
      Priority: input.Priority,
    }),
  });

  return (await res.json()) as Task;
}

export async function deleteTask(projectId: string, taskId: string): Promise<void> {
  assertProjectId(projectId);
  if (!taskId) throw new Error("deleteTask called with empty taskId");

  await apiFetch(`/projects/${projectId}/tasks/${taskId}`, { method: "DELETE" });
}
