// drag drop logik 
// använder findTask/findContainer från selectors.ts och isStatus från config.ts
import { useCallback } from "react";
import type { DragEndEvent } from "@dnd-kit/core";
import { arrayMove } from "@dnd-kit/sortable";

import type { Task, TaskStatus } from "../../../api/tasks";
import { updateTask } from "../../../api/tasks";
import { findTask } from "./selectors";
import { isStatus } from "./config";

type Params = {
  projectId: string;
  tasks: Task[];
  grouped: Record<TaskStatus, Task[]>;
  syncing: boolean;
  setSyncing: (v: boolean) => void;
  setError: React.Dispatch<React.SetStateAction<string | null>>;
  persistColumn: (status: TaskStatus, ordered: Task[]) => Promise<void>;
  reload: () => Promise<void>;
};

function asStatus(x: unknown): TaskStatus | null {
  if (typeof x !== "string") return null;
  return isStatus(x) ? (x as TaskStatus) : null;
}

export function useBoardDrag({
  projectId,
  tasks,
  grouped,
  syncing,
  setSyncing,
  setError,
  persistColumn,
  reload,
}: Params) {
  const onDragEnd = useCallback(
    async (e: DragEndEvent) => {
      if (syncing) return;
      setSyncing(true);

      try {
        const activeId = String(e.active.id);
        const overId = e.over?.id ? String(e.over.id) : null;
        if (!overId) return;

        const activeTask = findTask(tasks, activeId);
        if (!activeTask) return;

        const activeSortable = e.active.data.current?.sortable as
          | { index: number; containerId: string }
          | undefined;

        const overSortable = e.over?.data.current?.sortable as
          | { index: number; containerId: string }
          | undefined;

        // from = containerId om vi får den, annars taskens status
        const from = asStatus(activeSortable?.containerId) ?? activeTask.Status;

        // dropOnColumn => över kolumn-yta
        const dropOnColumn = isStatus(overId);

        // to = över kolumn (om dropOnColumn), annars containerId från overSortable
        const to = dropOnColumn
          ? (overId as TaskStatus)
          : asStatus(overSortable?.containerId);

        if (!to) return;

        // -------------------------
        // 1) REORDER I SAMMA KOLUMN
        // -------------------------
        if (from === to) {
          const items = grouped[to].slice(); // sorterad på Priority

          // Släpp på kolumnens yta => flytta sist
          if (dropOnColumn) {
            const fromIndex = items.findIndex((t) => t.Id === activeId);
            if (fromIndex === -1) return;

            const next = items.slice();
            const [moved] = next.splice(fromIndex, 1);
            next.push(moved);

            await persistColumn(to, next);
            return;
          }

          // dnd-kit index om möjligt
          const fromIndex = activeSortable?.index;
          const toIndex = overSortable?.index;

          if (typeof fromIndex !== "number" || typeof toIndex !== "number") {
            // fallback
            const fi = items.findIndex((t) => t.Id === activeId);
            const oi = items.findIndex((t) => t.Id === overId);
            if (fi === -1 || oi === -1) return;

            await persistColumn(to, arrayMove(items, fi, oi));
            return;
          }

          if (fromIndex === toIndex) return;

          const next = arrayMove(items, fromIndex, toIndex);
          await persistColumn(to, next);
          return;
        }

        // -------------------------
        // 2) FLYTT MELLAN KOLUMNER
        // -------------------------
        // a) bygg listor i UI
        const fromItems = grouped[from].slice().filter((t) => t.Id !== activeId);
        const toItems = grouped[to].slice();

        const movedTo: Task = { ...activeTask, Status: to };

        // b) bestäm var den ska in i målkolumnen
        const nextTo = toItems.slice();

        if (dropOnColumn) {
          nextTo.push(movedTo); // sist
        } else {
          const insertIndex =
            typeof overSortable?.index === "number"
              ? overSortable.index
              : toItems.findIndex((t) => t.Id === overId);

          if (insertIndex < 0) nextTo.push(movedTo);
          else nextTo.splice(insertIndex, 0, movedTo);
        }

        // c) uppdatera taskens status i DB FÖRST
        // annars failar backend reorder-checken (tasken ligger kvar i gamla statusen)
        await updateTask(projectId, activeTask.Id, {
          Title: activeTask.Title,
          Description: activeTask.Description ?? null,
          Status: to,
          Priority: 0, // backend lägger sist om <=0 (du har logik för det)
        });

        // d) reorder båda kolumnerna (atomiskt per kolumn)
        await persistColumn(from, fromItems);
        await persistColumn(to, nextTo);
      } catch (err: any) {
        setError(err?.message ?? "Move/Reorder failed");
        try {
          await reload();
        } catch (reloadErr: any) {
          setError((prev) => `${prev ?? ""}\nRefresh failed: ${String(reloadErr)}`);
        }
      } finally {
        setSyncing(false);
      }
    },
    [projectId, tasks, grouped, syncing, setSyncing, setError, persistColumn, reload]
  );

  return onDragEnd;
}
